from pathlib import Path
import json
catalog=json.loads((Path(__file__).resolve().parents[1]/'英语词根资料库/data/条目清单.json').read_text())
old=next(r for r in catalog if r['id']=='C0795')
extras={'naive','naivety','neonate','neonatal','nationalize','naturalize','naturalization','nee'}
assert len(words)==85,len(words)
assert {w['word'] for w in words}==set(old['family'])|extras
assert len({w['word'] for w in words})==len(words)
root=dict(id='C0795',meaning='出生；长出来；由出生发展出的本性、出身和亲缘',core='NASC / NAT = BE BORN',image='嫩芽长出来 → 生来带着什么 → 从哪里来、与谁同源',
intro='**nasc-/nat- 的起点很朴素：一个生命出生，或一个新东西长出来。** 拉丁语 nāscī 是“出生、生长”，nātus 是同族的“已出生”形态。出生时带来的样子，可以成为 nature“本性”；按出生和出身联系起来的人群，走向 nation；刚刚形成的事物，则是 nascent。先抓住这个动作，再看每个分支怎样发展。',
forms='**nasc-、nat- 和 gn- 是历史留下的不同形态。** nascent 保留“正在出生”的形式；natal、native 保留 nat-；cognate、agnate 一类还看得到旧的 gn-。法语 naître“出生”、né / née“出生的”以及 renaissance“重生”也来自这一支。pregnant 的远源解释带有不确定性；不要把看起来相似的字母自动拼成一段确定历史。',
branches=[['出生与新生','natal · prenatal · neonatal · nascent'],['出生时的性质','nature · natural · native · innate'],['出身联系成共同体','nation · national · nationality'],['自然、本性向外延伸','naturalist · naturalize · denature'],['再次长出来','renaissance · renascence · renascent'],['共同出生与亲缘','cognate · agnate · enate · connate']],
contrasts='**nature / nation**：nature 看“事物本来是什么样”；nation 看“一个人群怎样形成共同体”。它们共享出生的远源，却不能彼此替换。\n\n**native / naive**：都能追到拉丁语 nātīvus；native 多说本地、天生，naive 经法语发展出质朴、缺乏经验的意思。同源不等于同义。\n\n**nationalize / naturalize**：前者是国有化；后者可指使入籍、使植物归化。对应名词 nationalization / naturalization 也必须分清。\n\n**naturalist / naturist**：naturalist 常研究、观察自然；naturist 主要指崇尚自然裸体生活方式的人。少一个 al，身份就变了。\n\n**adnate / connate**：植物学里常用前者说不同类别器官贴生，后者说同类器官合生；不能都含糊地背成“长在一起”。\n\n**impregnable**：普通义“坚不可摧”来自“不能攻取”，属于另一条词源。这里只连带说明其罕见的 impregnate 派生同形义，绝不能把坚固城堡解释成“不怀孕”。\n\n**nada**：西班牙语“没有什么”背后有拉丁语“出生之物”在否定表达中的特殊历史。这是一段语言用法变化，不能按字面把出生直接等同于没有。',
practice='把“出生”这个画面换到三种场景：**A native plant, a nascent idea, and a renascent tradition all tell different stories of origin.**\n\n一种本地植物、一个初生观念和一项复兴传统，讲的是三种不同的起点。native 问原来属于哪里；nascent 问是否刚开始形成；renascent 问是否重新兴起。再试着用 innate、nationality 和 naturalize 分别说天生特质、国籍与入籍，别把出身、身份和后来取得的地位混为一谈。',
words=list(old['family'])+sorted(extras-set(old['family'])))
save('nat',[root],words)
